package com.coraline.feast;

import com.coraline.otherworld.*;
import com.coraline.secrets.*;
import com.mojang.authlib.GameProfile;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraftforge.gametest.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class EventRevisionGameTests {
    static ServerPlayer fixture(GameTestHelper h){var l=h.getLevel().getServer().getLevel(OtherWorld.KEY);var p=new ServerPlayer(l.getServer(),l,new GameProfile(UUID.randomUUID(),"EventRevisionQA"));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(p.server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);var s=new VisitData.Scene();s.owner=p.getUUID();s.door=UUID.randomUUID();s.stage=VisitData.Stage.DONE;s.table=new BlockPos(98000,180,98000);s.piano=s.table.east(20);s.loop.phase=OtherMotherLoopState.Phase.GAME_NIGHT_GREETING;s.loop.event.putString("Type","FAMILY_GAME_NIGHT");s.loop.event.putInt("Serial",2);VisitData.get(p.server).scenes.put(s.owner,s);p.getPersistentData().putUUID("CoralineVisitDoor",s.door);p.setPos(s.table.getCenter());return p;}
    @GameTest(template="empty") public static void fatherGreetingDoesNotRestartWhileWaitingForSeats(GameTestHelper h){var p=fixture(h);var s=OtherMotherLoop.scene(p);try{var n=s.loop.event;String greeting="father_game_night_greeting_1";n.putString("Greeting",greeting);n.putString("FatherVoice",greeting);n.putInt("FatherVoiceLength",VisitAudio.length(greeting));n.putInt("FatherVoiceElapsed",VisitAudio.length(greeting));n.putBoolean("FatherVoiceFinished",true);h.assertTrue(FamilyGameNight.greetingFinished(p,s),"Completed greeting not latched");for(int i=0;i<200;i++)h.assertTrue(FamilyGameNight.greetingFinished(p,s),"Greeting restarted while waiting");h.assertTrue(n.getString("FatherVoice").isEmpty()&&n.getBoolean("GameFatherGreetingDone"),"Welcome line requeued");h.assertTrue(OtherMotherLoopState.load(s.loop.save()).event.getBoolean("GameFatherGreetingDone"),"Greeting latch lost across reload");}finally{VisitData.get(p.server).scenes.remove(s.owner);}h.succeed();}
    @GameTest(template="empty") public static void debugBookUnlocksEligibleWybieAndPreservesBans(GameTestHelper h){var p=fixture(h);var s=OtherMotherLoop.scene(p);try{p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);com.coraline.item.NeighborVisitsDebugItem.complete(p);h.assertTrue(WybieOptionalVisits.allowed(s)&&s.loop.story.getBoolean("NeighborVisitsDebugComplete"),"Book didn't unlock optional Other Wybie");s.loop.story.putBoolean("WybieVisitsForbidden",true);com.coraline.item.NeighborVisitsDebugItem.complete(p);h.assertFalse(WybieOptionalVisits.allowed(s),"Book erased a deliberate story ban");}finally{VisitData.get(p.server).scenes.remove(s.owner);}h.succeed();}
    @GameTest(template="empty") public static void picnicRequiresActivitiesNotIdleTime(GameTestHelper h){var n=new net.minecraft.nbt.CompoundTag();n.putInt("OutingElapsed",99999);h.assertFalse(FamilyOuting.picnicFinished(n),"Idle time completed picnic");h.assertTrue(FamilyOuting.picnicObjective(n).contains("basket"),"Missing unpack objective");n.putBoolean("PicnicUnpacked",true);h.assertTrue(FamilyOuting.picnicObjective(n).contains("flower"),"Missing exploration objective");n.putInt("PicnicFlowers",3);n.putInt("PicnicServed",3);n.putBoolean("PicnicTasted",true);h.assertTrue(FamilyOuting.picnicObjective(n).contains("Pack"),"Missing finish interaction");n.putBoolean("PicnicPacked",true);h.assertTrue(FamilyOuting.picnicFinished(n),"Packed picnic cannot finish");h.succeed();}
    @GameTest(template="empty") public static void circusUsesOriginalTreats(GameTestHelper h){h.assertTrue(CircusSouvenirs.COTTON_CANDY.get()==com.coraline.food.TreatFoods.ITEMS.get("cotton_candy").get(),"Duplicate cotton candy issued");h.assertTrue(CircusSouvenirs.POPCORN.get()==com.coraline.food.TreatFoods.ITEMS.get("popcorn").get(),"Duplicate popcorn issued");h.succeed();}
}
